function truncateSlackMessage(inputMessage, maxLength = 2900) {
  // Check if truncation is needed
  if (inputMessage.length <= maxLength) {
    return {message: JSON.stringify(inputMessage).slice(1, -1), truncated: false};
  }

  // Truncate the message
  let truncatedMessage = inputMessage.substring(0, maxLength);

  // Add an indicator that the message was truncated
  truncatedMessage += "... [Message truncated due to length limits].";

  return {
    message: JSON.stringify(truncatedMessage).slice(1, -1), 
    truncated: true,
    messageLength: truncatedMessage.length
  };
}

